declare @HasViewPermission int select @HasViewPermission = HAS_PERMS_BY_NAME(null, null, 'VIEW SERVER STATE') create table #tmp_db_ars (replica_id uniqueidentifier, group_id uniqueidentifier, replica_server_name sysname) create table #tmp_db_ags (group_id uniqueidentifier, name sysname) create table #tmp_db_hadr_dbrs (group_database_id uniqueidentifier, synchronization_state tinyint, is_local bit, group_id uniqueidentifier, database_id int) create table #tmp_sync_states (database_id int, sync_state tinyint) if (@HasViewPermission = 1) begin insert into #tmp_db_ars select replica_id, group_id, replica_server_name from master.sys.availability_replicas insert into #tmp_db_ags select group_id, name from master.sys.availability_groups end if (@HasViewPermission = 1) begin insert into #tmp_db_hadr_dbrs select group_database_id, synchronization_state, is_local, group_id, database_id from master.sys.dm_hadr_database_replica_states end if (@HasViewPermission = 1) begin if serverproperty('EngineEdition') = 8 begin insert into #tmp_sync_states select dtb.database_id, hadrd.synchronization_state as synchronization_state from sys.databases AS dtb join #tmp_db_hadr_dbrs AS hadrd ON hadrd.database_id = dtb.database_id AND hadrd.is_local = 1 join #tmp_db_ags AS avag ON hadrd.group_id = avag.group_id join #tmp_db_ars AS avar ON avag.name = avar.replica_server_name join #tmp_db_ags AS avag2 ON avar.group_id = avag2.group_id where hadrd.database_id = dtb.database_id end else begin insert into #tmp_sync_states select dtb.database_id, hadrd.synchronization_state from sys.databases AS dtb join #tmp_db_hadr_dbrs AS hadrd ON hadrd.database_id = dtb.database_id AND hadrd.is_local = 1 end end SELECT dtb.name AS [Database_Name], 'Server[@Name=' + quotename(CAST( serverproperty(N'Servername') AS sysname),'''') + ']' + '/Database[@Name=' + quotename(dtb.name,'''') + ']' AS [Database_Urn], dtb.containment AS [Database_ContainmentType], dtb.recovery_model AS [Database_RecoveryModel], ISNULL(suser_sname(dtb.owner_sid),'') AS [Database_Owner], case when dtb.collation_name is null then 0x200 else 0 end | case when 1 = dtb.is_in_standby then 0x40 else 0 end | case dtb.state when 1 then 0x2 when 2 then 0x8 when 3 then 0x4 when 4 then 0x10 when 5 then 0x100 when 6 then 0x20 else 1 end AS [Database_Status], dtb.compatibility_level AS [Database_CompatibilityLevel], ISNULL(dmi.mirroring_role,0) AS [Database_MirroringRole], ISNULL(dmi.mirroring_state + 1, 0) AS [Database_MirroringStatus], sync_state.sync_state AS [Database_AvailabilityDatabaseSynchronizationState], 0 AS [Database_HasMemoryOptimizedObjects], CAST(0 AS bit) AS [Database_RemoteDataArchiveEnabled], CAST( case when SERVERPROPERTY('EngineEdition') = 6 then cast(1 as bit) else cast(0 as bit) end AS bit) AS [Database_IsSqlDw], case when SERVERPROPERTY('EngineEdition') = 8 then SERVERPROPERTY('IsFullTextInstalled') else dtb.is_fulltext_enabled end AS [Database_IsFullTextEnabled], CAST(ISNULL(dtb.is_ledger_on, 0) AS bit) AS [Database_IsLedger], dtb.recovery_model AS [RecoveryModel], dtb.user_access AS [UserAccess], dtb.is_read_only AS [ReadOnly], dtb.name AS [Database_DatabaseName2], dtb.name AS [Database_DatabaseName3] FROM master.sys.databases AS dtb LEFT OUTER JOIN sys.database_mirroring AS dmi ON dmi.database_id = dtb.database_id LEFT OUTER JOIN #tmp_sync_states AS sync_state ON dtb.database_id = sync_state.database_id WHERE (CAST(case when dtb.name in ('master','model','msdb','tempdb') then 1 else dtb.is_distributor end AS bit)=@_msparam_0 and CAST(isnull(dtb.source_database_id, 0) AS bit)=@_msparam_1) ORDER BY [Database_Name] ASC drop table #tmp_db_ars drop table #tmp_db_ags drop table #tmp_db_hadr_dbrs drop table #tmp_sync_states
